import {contact,categories,products,works,materials,guides,faqs,bundles,calculatePrice,money,priceMeta,validContact} from './data.js';

const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={arrow:'M4 12h16m-6-6 6 6-6 6',diagonal:'M6 18 18 6M6 6h12v12',search:'m21 21-5-5M18 10.5a7.5 7.5 0 1 1-15 0 7.5 7.5 0 0 1 15 0',menu:'M4 7h16M4 12h16M4 17h16',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4 10-10',plus:'M12 5v14M5 12h14',minus:'M5 12h14',upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5',file:'M14 2H5v20h14V7ZM14 2v6h5M8 13h8M8 17h6',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',phone:'M7 3H3c-1 10 8 19 18 18v-4l-5-2-2 2-7-7 2-2Z',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',chevron:'m6 9 6 6 6-6',bag:'M5 7h14l2 14H3ZM8 8V6a4 4 0 0 1 8 0v2',copy:'M8 8h13v13H8ZM16 4V2H2v14h2',download:'M12 3v13m-5-5 5 5 5-5M4 18v4h16v-4',mail:'M2 5h20v14H2ZM2 5l10 8L22 5',leaf:'M20 3C7 2 1 10 6 16c6 5 14-1 14-13ZM5 21 17 7',grid:'M3 3h7v7H3ZM14 3h7v7h-7ZM3 14h7v7H3ZM14 14h7v7h-7',info:'M12 11v6m0-10v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',heart:'M12 21 3 12C-3 4 7-1 12 5c5-6 15-1 9 7Z',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.arrow}"/></svg>`;
const imageSrc=name=>name.endsWith('-art')?`./assets/illustrations/${name}.svg`:`./assets/photos/${name==='certificates'?'business-cards':name}.webp`;
const photo=(name,alt='',cls='',eager=false)=>`<img class="${cls}" src="${imageSrc(name)}" alt="${esc(alt)}" ${eager?'fetchpriority="high"':'loading="lazy"'} decoding="async" width="1080" height="1080">`;
const link=(url,label,cls='text-link')=>`<a href="${url}" class="${cls}">${label}${icon('arrow')}</a>`;
const sectionHead=(n,label,title,extra='')=>`<div class="section-head"><div><div class="eyebrow"><span class="section-no">${n}</span>${label}</div><h2>${title}</h2></div>${extra}</div>`;
const breadcrumb=(label)=>`<div class="container breadcrumb"><a href="#/">Главная</a><span>/</span><span>${label}</span></div>`;
const faqBlock=(items=faqs)=>`<div class="faq-list">${items.map(([q,a])=>`<details><summary>${q}${icon('plus')}</summary><div class="faq-answer">${a}</div></details>`).join('')}</div>`;
let route='/', config={}, currentProduct=null, drawerItems=[], selectedFiles=[], modalReturn=null;
let drafts; try {drafts=JSON.parse(localStorage.getItem('popygai-drafts')||'[]');if(!Array.isArray(drafts)) drafts=[];} catch {drafts=[];}
let observer;

function headerMarkup(){
 return `<div class="utility"><div class="container utility-inner"><a href="#/contacts">${icon('pin')}Минск, Гикало, 28 <span class="utility-muted">· за ЦУМом</span></a><span class="utility-center">Идеи обретают форму</span><a href="tel:${contact.tel}">${contact.phone}</a><span class="utility-hours">${contact.hours}</span></div></div>
 <header class="header"><div class="container nav"><a href="#/" class="brand" aria-label="Попугай — главная"><img class="brand-bird" src="./assets/brand/parrot.png" alt=""><span><img class="wordmark" src="./assets/brand/wordmark-tight.svg" alt="Popygai.by"><span class="brand-caption">ПЕЧАТАЕМ ВАШИ ИДЕИ</span></span></a><nav aria-label="Основная навигация"><a href="#/catalog" data-nav="catalog">Каталог${icon('chevron')}</a><a href="#/business" data-nav="business">Для бизнеса</a><a href="#/works" data-nav="works">Наши работы</a><a href="#/about" data-nav="about">О нас</a><a href="#/contacts" data-nav="contacts">Контакты</a></nav><div class="nav-actions"><button class="icon-button" data-action="search" aria-label="Поиск по сайту">${icon('search')}</button><button class="btn btn-dark nav-quote" data-action="quote">Обсудить заказ${icon('diagonal')}</button><button class="icon-button mobile-toggle" data-action="menu" aria-label="Открыть меню">${icon('menu')}</button></div></div></header>`;
}
function footerMarkup(){
 return `<section class="footer-invite"><div class="container invite-inner"><div class="invite-bird"><img src="./assets/brand/parrot.png" alt="Попугай"></div><div><div class="eyebrow">ДАВАЙТЕ СДЕЛАЕМ ЧТО-ТО ВАШЕ</div><h2>Есть идея?<br>Дадим ей форму.</h2></div><button class="btn btn-yellow" data-action="quote">Расскажите нам${icon('diagonal')}</button></div></section><footer class="footer"><div class="container"><div class="footer-grid"><div class="footer-brand"><a href="#/"><img src="./assets/brand/wordmark-white-tight.svg" alt="Popygai.by"></a><p>Полиграфия и сувениры<br>с вашим характером.</p><a class="footer-tg" href="${contact.telegram}" target="_blank" rel="noopener">Написать в Telegram ${icon('diagonal')}</a></div><div><h3>Что печатаем</h3>${categories.slice(1).map(c=>`<a href="#/catalog?category=${c.id}">${c.title}</a>`).join('')}</div><div><h3>Поможем разобраться</h3><a href="#/how">Как заказать</a><a href="#/materials">Материалы</a><a href="#/prices">Цены и расчёт</a><a href="#/guides">Полезное о печати</a><a href="#/orders">Мой заказ</a><a href="#/business">Для организаций</a></div><div><h3>Заглядывайте</h3><a href="#/contacts">Минск, Гикало, 28<br>За ЦУМом</a><p>${contact.hours}</p><a href="tel:${contact.tel}">${contact.phone}</a><a href="mailto:${contact.email}">${contact.email}</a><a class="footer-route" href="${contact.map}" target="_blank" rel="noopener">Построить маршрут ${icon('diagonal')}</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Попугай. Печатный центр.</span><span>ИП Фролов М. В. · УНП 192131673</span><a href="#/privacy">Конфиденциальность</a><span>Сделано с вниманием к деталям <span class="tiny-star">✳</span></span></div></div></footer><div class="mobile-bottom"><a href="#/catalog">${icon('grid')}Каталог</a><button data-action="quote">${icon('upload')}Отправить макет</button><a href="#/orders">${icon('bag')}Мой заказ</a></div>`;
}
function productCard(p){return `<article class="product-card"><a href="#/product/${p.id}" class="product-picture ${p.cat}">${photo(p.image,p.title)}<span class="picture-arrow">${icon('diagonal')}</span>${p.id==='business-cards'?'<span class="product-tag">НАЧНЁМ ЗНАКОМСТВО</span>':''}</a><div class="product-card-body"><span class="product-cat">${categories.find(c=>c.id===p.cat)?.title}</span><a href="#/product/${p.id}"><h3>${p.title}</h3></a><p>${p.spec}</p><div class="product-card-bottom"><span>${p.price?`<strong>${money(p.price)} BYN</strong><small>${p.unit}</small>`:'<strong>Под вашу задачу</strong><small>Индивидуальный расчёт</small>'}</span><a href="#/product/${p.id}" aria-label="Настроить: ${p.title}" class="round-button">${icon('arrow')}</a></div></div></article>`;}
function workCard(w,index=0){return `<a href="#/work/${w.id}" class="work-card"><div class="work-image">${photo(w.image,w.title)}<span class="work-open">Посмотреть работу ${icon('diagonal')}</span></div><div class="work-caption"><div><span>${w.type}</span><h3>${w.title}</h3></div><span class="work-index">0${index+1}${icon('diagonal')}</span></div></a>`;}
function steps(){return `<div class="steps">${[['01','Расскажите о задаче','Выберите изделие или просто опишите идею. Приложите макет, если он уже есть.'],['02','Согласуем детали','Проверим файл, подберём материал и подтвердим стоимость и срок.'],['03','Воплотим в печати','После вашего согласования подготовим и изготовим заказ.'],['04','Передадим в ваши руки','Сообщим о готовности. Забрать можно на Гикало, 28; доставку обсудим отдельно.']].map(([n,t,d])=>`<article class="step"><span class="step-number">${n}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div>`;}
function home(){return `
<section class="hero container"><div class="hero-copy"><div class="eyebrow"><span class="live-dot"></span>ПЕЧАТНЫЙ ЦЕНТР В МИНСКЕ</div><h1>Печатаем<br>ваши <span class="hero-ideas">идеи<svg viewBox="0 0 300 21" aria-hidden="true"><path d="M4 13Q130-1 294 9M19 19Q155 6 278 15"/></svg></span><span class="yellow-dot">.</span></h1><p class="hero-description">От первой визитки до целой коллекции мерча.<br class="desktop-br"> Полиграфия, сувениры и большие форматы —<br class="desktop-br"> с вниманием к вашей задумке.</p><div class="hero-buttons">${link('#/catalog','Что будем печатать?','btn btn-dark')}<button class="btn btn-outline" data-action="quote">${icon('upload')}У меня есть макет</button></div><div class="hero-footnote"><span class="little-line"></span><span>Поможем с макетом. Подберём материал.<br>Воплотим вашу идею.</span></div></div><div class="hero-art" aria-label="Настоящие работы типографии Попугай"><div class="art-grid"></div><span class="registration-mark reg-one">+</span><span class="registration-mark reg-two">+</span><div class="hero-photo hero-photo-main">${photo('cards','Визитки, напечатанные в типографии Попугай','',true)}<span class="photo-label">ВАШ БРЕНД. В ВАШИХ РУКАХ.</span></div><div class="hero-photo hero-photo-small">${photo('usb','Флешки с фирменным нанесением','',true)}<span>МАЛЕНЬКИЕ ВЕЩИ. БОЛЬШОЙ ХАРАКТЕР.</span></div><div class="hero-paper"><span class="paper-eyebrow">POPYGAI PRINT STUDIO</span><span class="paper-message">Хорошие идеи<br>должны быть<br><i>осязаемыми.</i></span><span class="paper-line"></span><img src="./assets/brand/wordmark-tight.svg" alt="Popygai.by"></div><div class="hero-stamp"><span>СДЕЛАНО</span><img src="./assets/brand/parrot.png" alt=""><span>В ПОПУГАЕ</span></div><span class="art-caption">01 / НАСТОЯЩИЕ РАБОТЫ. НАСТОЯЩИЙ ЦВЕТ.</span></div></section>
<div class="print-ribbon"><div class="container ribbon-inner"><span>${icon('spark')} ВАШ ДИЗАЙН</span><i>✳</i><span>НАША ПЕЧАТЬ</span><i>✳</i><span>МНОГО ВОЗМОЖНОСТЕЙ</span><i>✳</i><span>ОДИН ПОПУГАЙ</span><i>✳</i><span>МИНСК, ГИКАЛО, 28</span></div></div>
<section class="section container">${sectionHead('01','ПРОДУКЦИЯ','Для всего, что вы задумали.',link('#/catalog','Весь каталог'))}<div class="category-grid">${categories.slice(1).map((c,i)=>`<a class="category-card ${c.color}" href="#/catalog?category=${c.id}"><div class="category-card-top"><span>0${i+1}</span>${icon('diagonal')}</div><h3>${c.title}</h3><p>${c.items}</p><div class="category-thumb">${photo(c.image,c.title)}</div></a>`).join('')}</div><div class="catalog-help"><div>${icon('info')}<p>Знаете, что нужно, но не знаете, как называется?<br><strong>Просто расскажите. Мы разберёмся.</strong></p></div><button class="text-link" data-action="quote">Помогите мне выбрать ${icon('arrow')}</button></div></section>
<section class="section section-tint"><div class="container">${sectionHead('02','ЧАСТО ПЕЧАТАЕМ','Маленькие тиражи.<br>Большие впечатления.',link('#/prices','Как устроены цены'))}<div class="product-grid">${[products[0],products[1],products[2],products[5]].map(productCard).join('')}</div><p class="price-footnote">Цены для указанных комплектаций — по опубликованному прайсу. Итог подтверждается после проверки задания.</p></div></section>
<section class="section container materials-home">${sectionHead('03','ДЕЛО В ДЕТАЛЯХ','Разницу лучше почувствовать.',link('#/materials','Все материалы'))}<div class="material-feature"><div class="material-stage" id="material-stage">${materialVisual(materials[0])}</div><div class="material-content"><span class="eyebrow">БУМАГА — ТОЖЕ ЧАСТЬ ДИЗАЙНА</span><h3>У каждой идеи<br>своя фактура.</h3><p>Гладкая и строгая. Тёплая и натуральная. Необычная на ощупь. Выберите материал — и посмотрите, как меняется характер изделия.</p><div class="material-tabs" role="tablist" aria-label="Выбор материала">${materials.map((m,i)=>`<button role="tab" aria-selected="${!i}" data-material="${m.id}" class="${!i?'active':''}">${m.id==='coated'?'Мелованная':m.id==='touch'?'Дизайнерская':m.name}</button>`).join('')}</div><div id="material-detail" class="material-detail"><strong>${materials[0].feel}</strong><p>${materials[0].description}</p></div><a class="text-link" href="#/contacts">Посмотреть образцы в типографии ${icon('arrow')}</a></div></div></section>
<section class="business-band"><div class="container business-band-inner"><div><div class="eyebrow">ДЛЯ КОМАНД, БРЕНДОВ И БОЛЬШИХ ПЛАНОВ</div><h2>Ваш бизнес.<br>Ваш <i>характер.</i></h2><p>Визитки, упаковка, сувениры и оформление.<br>Соберём разные изделия в одну историю.</p>${link('#/business','Решения для бизнеса','btn btn-paper')}</div><div class="business-collage"><div class="business-photo">${photo('cap','Кепка с фирменной символикой')}</div><div class="business-note"><span>В ОДНОМ СТИЛЕ</span><p>От первой<br>визитки<br>до мерча<br>для команды.</p>${icon('diagonal')}</div><span class="business-star">✳</span></div></div></section>
<section class="section container">${sectionHead('04','СДЕЛАНО В ПОПУГАЕ','Хорошая печать говорит сама.',link('#/works','Больше наших работ'))}<div class="works-grid home-works">${[works[0],works[4],works[2]].map(workCard).join('')}</div></section>
<section class="section section-tint"><div class="container">${sectionHead('05','ПРОСТО ПО ПОРЯДКУ','От идеи до готового заказа.',link('#/how','Подробнее о процессе'))}${steps()}<div class="process-note"><img src="./assets/brand/parrot.png" alt=""><p><strong>Первый раз заказываете печать?</strong><br>Можно начать с «У меня есть идея». Остальное обсудим вместе.</p><button class="text-link" data-action="quote">Начать с идеи ${icon('arrow')}</button></div></div></section>
<section class="section container">${sectionHead('06','ПОЛЕЗНО ЗНАТЬ','Немного ясности перед печатью.',link('#/guides','Все памятки'))}<div class="guides-grid">${guides.slice(0,3).map(guideCard).join('')}</div></section>
<section class="section container faq-section"><div><div class="eyebrow"><span class="section-no">07</span>ОТВЕЧАЕМ ПО ДЕЛУ</div><h2>Возможно,<br>вы хотели спросить.</h2><p>А если вашего вопроса здесь нет —<br>мы на связи.</p><a class="text-link" href="${contact.telegram}" target="_blank" rel="noopener">Написать в Telegram ${icon('diagonal')}</a></div>${faqBlock()}</section>
<section class="visit-section"><div class="container visit-grid"><div class="visit-photo">${photo('interior','Интерьер печатного центра Попугай в Минске')}<span>ЗАГЛЯДЫВАЙТЕ. БУДЕМ РАДЫ.</span></div><div class="visit-copy"><div class="eyebrow">ВАШ ПЕЧАТНЫЙ ЦЕНТР РЯДОМ</div><h2>Увидимся<br>на Гикало, 28.</h2><p>В центре Минска, за ЦУМом.<br>Приходите за готовым заказом,<br>выбирать материалы и знакомиться.</p><div class="visit-hours">${icon('clock')}${contact.hours}</div><div class="visit-buttons">${link('#/contacts','Как нас найти','btn btn-dark')}<a href="tel:${contact.tel}" class="text-link">${contact.phone}</a></div></div></div></section>`;}

function materialVisual(m){return `<div class="paper-stack ${m.class}"><div class="paper-shadow"></div><div class="sample-paper"><span class="sample-brand">POPYGAI.BY</span><span class="sample-slogan">Всё дело<br>в <i>ощущениях.</i></span><div class="sample-bottom"><span>ХОРОШИЕ ИДЕИ<br>ПРИЯТНЫ НА ОЩУПЬ</span><span>✳</span></div></div><div class="sample-swatch"><span>${m.eyebrow}</span><strong>${m.name}</strong></div></div>`;}
function guideCard(g){return `<a href="#/guide/${g.id}" class="guide-card"><div class="guide-visual ${g.class}"><span class="guide-no">ПАМЯТКА / ${g.number}</span>${g.id==='file'?'<div class="guide-art-file"><span>PDF</span><i>✳</i><small>ГОТОВО К ПЕЧАТИ</small></div>':g.id==='paper'?'<div class="guide-art-papers"><i></i><i></i><i><span>Бумага<br>решает.</span></i></div>':g.id==='stickers'?'<div class="guide-art-stickers"><span>hi!</span><span>✳</span><span>ваше.</span></div>':'<div class="guide-art-file"><span>ЛОГО</span><i>↗</i></div>'}${icon('diagonal')}</div><div class="guide-meta">${g.category}<span>${g.read}</span></div><h3>${g.title}</h3><p>${g.desc}</p></a>`;}
function catalog(params){const active=params.get('category')||'all';return `${breadcrumb('Каталог')}<section class="container page-intro"><div class="eyebrow">ОТ МАЛЕНЬКОЙ ИДЕИ ДО БОЛЬШОГО ФОРМАТА</div><h1>Что будем <i>печатать?</i></h1><p>Выберите изделие. Разберёмся с материалом, макетом и всеми деталями.</p></section><section class="container catalog-section"><div class="catalog-toolbar"><div class="filter-tabs" aria-label="Категории продукции">${categories.map(c=>`<button data-filter="${c.id}" class="${active===c.id?'active':''}" aria-pressed="${active===c.id}">${c.title}</button>`).join('')}</div><label class="catalog-search">${icon('search')}<input id="catalog-search" type="search" placeholder="Найти изделие" aria-label="Найти изделие"></label></div><div class="results-label" id="results-label"></div><div class="product-grid catalog-grid" id="catalog-results"></div><div class="empty-state" id="catalog-empty" hidden><img src="./assets/brand/parrot.png" alt=""><h3>Попробуем другое название?</h3><p>Или расскажите о задаче — поможем подобрать изделие.</p><button class="btn btn-dark" data-action="quote">Обсудить идею ${icon('arrow')}</button></div><div class="custom-request"><span class="custom-star">✳</span><div><h2>Есть что-то особенное?</h2><p>Нестандартный размер, необычный материал или несколько изделий в одном заказе.</p></div><button class="btn btn-dark" data-action="quote">Обсудим вашу задачу ${icon('diagonal')}</button></div></section>`;}
function filterCatalog(category='all',query=''){
 const list=products.filter(p=>(category==='all'||p.cat===category)&&`${p.title} ${p.description} ${p.spec} ${p.uses.join(' ')} ${p.id==='stickers'?'стикеры этикетка':''} ${p.id==='documents'?'распечатка ксерокс копия':''}`.toLowerCase().includes(query.toLowerCase()));
 $('#catalog-results').innerHTML=list.map(productCard).join('');$('#catalog-empty').hidden=!!list.length;$('#results-label').textContent=`${list.length} ${list.length===1?'изделие':list.length>1&&list.length<5?'изделия':'изделий'} · найдём подходящее для вашей задачи`;
}
function fieldset(label,name,options,value){return `<fieldset class="option-field"><legend>${label}</legend><div class="option-buttons">${options.map(([v,t])=>`<label class="option ${String(value)===String(v)?'selected':''}"><input type="radio" name="${name}" value="${v}" ${String(value)===String(v)?'checked':''}>${t}</label>`).join('')}</div></fieldset>`;}
function productOptions(p){let html='';if(p.pricing==='cards'){html+=fieldset('Бумага','paper',[['coated','Мелованная'],['calendered','Каландрированная']],config.paper);html+=`<p class="option-hint">${config.sides==='two'?'300':'350'} г/м² · ${config.paper==='coated'?'гладкая универсальная основа':'плотная бумага с гладкой поверхностью'}</p>`;}if(['flyers','documents'].includes(p.pricing)){html+=fieldset('Формат','format',p.pricing==='documents'?[['A4','А4'],['A3','А3']]:[['A6','А6'],['A5','А5'],['A4','А4']],config.format);}if(p.pricing==='documents')html+=fieldset('Цветность','color',[['bw','Чёрно-белая'],['color','Цветная']],config.color);if(p.pricing!=='quote')html+=fieldset('Печать','sides',[['one','С одной стороны'],['two','С двух сторон']],config.sides);if(p.pricing==='quote')html+=`<label class="field-label">Материал или исполнение<select name="material">${p.materials.map(m=>`<option ${config.material===m?'selected':''}>${m}</option>`).join('')}</select></label><label class="field-label">Размер / модель<input name="customSize" placeholder="${p.format}" value="${esc(config.customSize||'')}"></label>`;html+=`<label class="field-label">${p.pricing==='documents'?'Количество физических листов':'Тираж, шт.'}<div class="quantity-input"><button type="button" data-quantity="minus" aria-label="Уменьшить количество">${icon('minus')}</button><input name="quantity" type="number" min="${p.pricing==='cards'?96:p.pricing==='flyers'?100:1}" max="100000" step="${p.pricing==='cards'?96:p.pricing==='flyers'?100:1}" value="${config.quantity}" required><button type="button" data-quantity="plus" aria-label="Увеличить количество">${icon('plus')}</button></div></label>`;if(p.pricing==='cards')html+='<p class="option-hint">Комплект — 96 шт. одного макета. Количество кратно 96.</p>';if(p.pricing==='flyers')html+='<p class="option-hint">Расчёт комплектами по 100 шт. одного макета.</p>';return html;}
function productPage(id){const p=products.find(p=>p.id===id);if(!p)return notFound();currentProduct=p;config={paper:'coated',format:p.pricing==='flyers'?'A6':'A4',sides:'one',color:'bw',quantity:p.pricing==='cards'?96:p.pricing==='flyers'?100:p.pricing==='documents'?10:['stickers','stickerpacks','pens','usb','caps'].includes(p.id)?50:1,material:p.materials[0]};return `${breadcrumb(`<a href="#/catalog">Каталог</a> / ${p.title}`)}<section class="container product-page"><div class="product-gallery"><div class="product-main-photo">${photo(p.image,p.title,'',true)}<span class="gallery-note">${p.image.endsWith('-art')?'ПРИМЕР ОФОРМЛЕНИЯ ИЗДЕЛИЯ':'РЕАЛЬНАЯ РАБОТА ИЗ ПОРТФОЛИО'}</span><button class="photo-zoom icon-button" data-lightbox="${p.image}" data-caption="${p.title}" aria-label="Увеличить фотографию">${icon('plus')}</button></div><div class="product-detail-strip"><span>${icon('check')}Макет согласуем до печати</span><span>${icon('pin')}Самовывоз: Гикало, 28</span></div><div class="product-side-note"><span>${p.image.endsWith('-art')?'Иллюстрация показывает пример изделия.':'На фото — пример выполненной работы.'} Дизайн и параметры вашего изделия согласуются отдельно.</span></div></div><div class="product-config"><div class="eyebrow">${categories.find(c=>c.id===p.cat)?.title}</div><h1>${p.title}</h1><p class="product-lead">${p.description}</p><form id="product-config-form"><div id="product-options">${productOptions(p)}</div><div class="quote-summary" aria-live="polite"><div class="summary-row"><span>${p.pricing==='quote'?'Стоимость':'Предварительный расчёт'}</span><strong id="quote-total"></strong></div><div id="quote-breakdown" class="quote-breakdown"></div><p class="summary-note" id="quote-note"></p><button type="submit" class="btn btn-dark btn-full">${p.pricing==='quote'?'Запросить расчёт':'Продолжить с этим вариантом'}${icon('arrow')}</button><p class="under-button">Без оплаты. Сначала подтвердим детали и срок.</p></div></form></div></section><section class="section section-tint"><div class="container product-info-grid"><div><div class="eyebrow">ДЕТАЛИ ИЗДЕЛИЯ</div><h2>${p.tag}</h2><p class="body-large">${p.details}</p><div class="use-tags">${p.uses.map(t=>`<span>${t}</span>`).join('')}</div></div><div class="spec-sheet"><h3>Что согласуем перед печатью</h3><dl><div><dt>Размер</dt><dd>${p.format}</dd></div><div><dt>Материалы</dt><dd>${p.materials.join(' / ')}</dd></div><div><dt>Макет</dt><dd>Ваш или разработанный с нами</dd></div><div><dt>Срок</dt><dd>После проверки и подтверждения задания</dd></div><div><dt>Получение</dt><dd>Гикало, 28 · доставку обсудим</dd></div></dl></div></div></section><section class="section container product-info-grid"><div><div class="eyebrow">ГОТОВИМ ФАЙЛ</div><h2>Хороший результат<br>начинается с макета.</h2><p class="body-large">Не уверены в подготовке? Приложите файл к заявке и попросите специалиста проверить его.</p>${link('#/guide/file','Памятка по подготовке')}</div><div>${faqBlock(faqs.slice(0,4))}</div></section><section class="section container">${sectionHead('ЕЩЁ','МОЖЕТ ПРИГОДИТЬСЯ','В одной истории с вашим заказом.')}<div class="product-grid">${products.filter(x=>x.id!==id).sort((a,b)=>(b.cat===p.cat)-(a.cat===p.cat)).slice(0,4).map(productCard).join('')}</div></section>`;}
function updateQuote(){if(!currentProduct)return;const p=currentProduct;const total=calculatePrice(p.id,config);$('#quote-total').textContent=total!==null?`${money(total)} BYN`:p.pricing==='quote'?'По запросу':'Уточните параметры';$('#quote-breakdown').textContent=total!==null?`${config.quantity} ${p.pricing==='documents'?'листов':'шт.'} · ${money(total/Number(config.quantity))} BYN за ${p.pricing==='documents'?'лист':'шт.'}`:p.pricing==='quote'?'Подберём исполнение и подготовим предложение.':'Проверьте количество и выбранные параметры.';$('#quote-note').innerHTML=total!==null?`${priceMeta.note} <a href="#/prices">Об условиях расчёта</a>`:'Материал, тираж и макет проверим до подтверждения стоимости.';$('#product-config-form button[type=submit]').disabled=p.pricing!=='quote'&&total===null;}

function businessPage(){return `${breadcrumb('Для бизнеса')}<section class="container editorial-hero"><div><div class="eyebrow">ДЛЯ БРЕНДОВ, КОМАНД И БОЛЬШИХ ПЛАНОВ</div><h1>Ваш бизнес.<br>Ваш <i>характер.</i></h1><p>Фирменная полиграфия, сувениры и оформление. Поможем собрать разные изделия в один продуманный заказ.</p><button class="btn btn-dark" data-action="quote">Обсудить проект ${icon('diagonal')}</button><a href="mailto:${contact.businessEmail}" class="quiet-link">${contact.businessEmail}</a></div><div class="editorial-picture">${photo('cap','Фирменное нанесение на кепку','',true)}<span class="editorial-sticker">ОДИН БРЕНД.<br>МНОГО ФОРМ.</span></div></section><section class="section section-tint"><div class="container">${sectionHead('01','НАЧНИТЕ С ЗАДАЧИ','Соберём нужное. В вашем стиле.')}<div class="bundle-grid">${bundles.map(b=>`<article class="bundle-card"><div class="bundle-image">${photo(b.image,b.title)}</div><div class="bundle-body"><span class="eyebrow">${b.label}</span><h3>${b.title}</h3><p>${b.text}</p><div class="bundle-items">${b.items.map(id=>{const p=products.find(x=>x.id===id);return `<label><input type="checkbox" data-bundle-item="${b.id}" value="${id}" checked>${p.title}</label>`;}).join('')}</div><button class="text-link" data-bundle="${b.id}">Обсудить этот комплект ${icon('arrow')}</button></div></article>`).join('')}</div></div></section><section class="section container split-section"><div><div class="eyebrow">ОДНО ПИСЬМО ВМЕСТО ДЕСЯТИ</div><h2>Несколько изделий.<br>Один понятный процесс.</h2><p class="body-large">Пришлите список позиций, тиражи, нужную дату и брендбук. Специалист проверит возможности и подготовит состав заказа.</p><button class="btn btn-dark" data-action="quote">Собрать заявку ${icon('arrow')}</button></div><div class="business-services">${[['Расчёт по вашему заданию','Объединим позиции в предложение с параметрами и стоимостью.'],['Согласование оформления','Проверим расположение логотипа и версии макетов для разных изделий.'],['Документы для организации','Передайте реквизиты. Условия оплаты и состав документов согласуем до запуска.'],['Повторение заказа','Сохраните описание своего заказа, чтобы в следующий раз быстрее вернуться к нужным параметрам.']].map(([t,d],i)=>`<div><span>0${i+1}</span><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}</div></section><section class="section container">${sectionHead('02','ИЗ ПРАКТИКИ','Посмотрите, как это выглядит.',link('#/works','Все работы'))}<div class="works-grid">${works.filter(w=>w.cat==='gifts').slice(0,3).map(workCard).join('')}</div></section><section class="section section-tint"><div class="container faq-section"><div><div class="eyebrow">ДО НАЧАЛА РАБОТЫ</div><h2>Давайте уточним<br>главное.</h2></div>${faqBlock([faqs[4],faqs[1],faqs[2],faqs[0]])}</div></section>`;}
function worksPage(params){const active=params.get('category')||'all';return `${breadcrumb('Наши работы')}<section class="container page-intro"><div class="eyebrow">ПОРТФОЛИО ПЕЧАТНОГО ЦЕНТРА</div><h1>Уже стали <i>осязаемыми.</i></h1><p>Настоящие работы «Попугая». Рассмотрите материалы, нанесение и детали.</p></section><section class="container section-bottom"><div class="filter-tabs work-filters">${[['all','Все работы'],['print','Полиграфия'],['gifts','Сувениры и мерч'],['wide','Большие форматы']].map(([id,title])=>`<a class="${active===id?'active':''}" href="#/works?category=${id}">${title}</a>`).join('')}</div><div class="works-grid portfolio-grid">${works.filter(w=>active==='all'||w.cat===active).map(workCard).join('')}</div><p class="price-footnote">Фото из опубликованного портфолио типографии. Логотипы и дизайн заказчиков принадлежат их правообладателям.</p></section>`;}
function workPage(id){const w=works.find(x=>x.id===id);if(!w)return notFound();return `${breadcrumb(`<a href="#/works">Наши работы</a> / ${w.title}`)}<section class="container case-header"><div class="eyebrow">${w.type} · ИЗ ПОРТФОЛИО ПОПУГАЯ</div><h1>${w.title}</h1><p>${w.subtitle}</p></section><section class="container case-main"><button class="case-photo" data-lightbox="${w.image}" data-caption="${w.title}" aria-label="Увеличить фото работы">${photo(w.image,w.title,'',true)}<span>${icon('plus')}Рассмотреть детали</span></button><aside class="case-story"><div class="eyebrow">О РАБОТЕ</div><h2>${w.subtitle}</h2><p>${w.text}</p><dl>${w.focus.map((s,i)=>`<div><dt>0${i+1}</dt><dd>${s}</dd></div>`).join('')}</dl><p class="small-text">Точный материал, тираж и параметры этой работы не опубликованы. Для похожего проекта подготовим индивидуальное предложение.</p><button class="btn btn-dark" data-similar="${w.product}">Хочу похожий результат ${icon('diagonal')}</button></aside></section><section class="section container">${sectionHead('ЕЩЁ','РАБОТЫ ТИПОГРАФИИ','Каждая идея — со своим характером.')}<div class="works-grid">${works.filter(x=>x.id!==id).slice(0,3).map(workCard).join('')}</div></section>`;}
function materialsPage(){return `${breadcrumb('Материалы')}<section class="container page-intro"><div class="eyebrow">ФАКТУРА. ЦВЕТ. ВПЕЧАТЛЕНИЕ.</div><h1>Характер начинается<br>с <i>материала.</i></h1><p>Подберём основу под изделие и условия использования. А образцы можно рассмотреть в типографии.</p></section><section class="container materials-list">${materials.map((m,i)=>`<article class="material-row"><div class="material-stage">${materialVisual(m)}</div><div><div class="eyebrow">0${i+1} / ${m.eyebrow}</div><h2>${m.name}</h2><p class="body-large">${m.feel}</p><p>${m.description}</p><div class="material-best"><span>ПОДОЙДЁТ ДЛЯ</span><strong>${m.best}</strong></div>${link('#/product/'+m.link,'Выбрать изделие')}</div></article>`).join('')}</section><section class="section section-tint"><div class="container split-section"><div><div class="eyebrow">ЛУЧШЕ ОДИН РАЗ ПОТРОГАТЬ</div><h2>Приходите<br>за ощущениями.</h2></div><div><p class="body-large">Фотография помогает сравнить внешний вид. Образец — почувствовать плотность и поверхность. Наличие конкретных образцов уточните перед визитом.</p>${link('#/contacts','Как нас найти','btn btn-dark')}</div></div></section>`;}
function guidesPage(){return `${breadcrumb('Полезное о печати')}<section class="container page-intro"><div class="eyebrow">ПОНЯТНО О ТОМ, ЧТО ВАЖНО</div><h1>Чуть больше <i>ясности.</i></h1><p>Короткие памятки, которые помогают выбрать изделие и подготовиться к печати.</p></section><section class="container section-bottom"><div class="guides-grid guides-full">${guides.map(guideCard).join('')}</div></section>`;}
function guidePage(id){const g=guides.find(x=>x.id===id);if(!g)return notFound();return `${breadcrumb(`<a href="#/guides">Полезное</a> / ${g.category}`)}<article class="container article-page"><aside class="article-nav"><span class="eyebrow">СОДЕРЖАНИЕ</span>${g.sections.map(([t],i)=>`<a href="#article-${i}" data-scroll="article-${i}">0${i+1} ${t}</a>`).join('')}<button class="text-link" data-action="quote">Нужна помощь? ${icon('arrow')}</button></aside><div class="article-content"><div class="eyebrow">${g.category} · ${g.read}</div><h1>${g.title}</h1><p class="article-lead">${g.desc}</p><div class="article-rule">✳ ПАМЯТКА ОТ ПОПУГАЯ</div>${g.sections.map(([t,d],i)=>`<section id="article-${i}"><span class="section-no">0${i+1}</span><h2>${t}</h2><p>${d}</p></section>`).join('')}<div class="article-callout"><img src="./assets/brand/parrot.png" alt=""><p><strong>Не обязательно разбираться во всём самостоятельно.</strong><br>Опишите задачу и покажите файл специалисту до запуска.</p></div><div class="article-source">Основа памятки — услуги и требования печатного центра. Параметры конкретного изделия уточняйте перед изготовлением. <a href="https://popygai.by/requirements" target="_blank" rel="noopener">Официальные требования ${icon('diagonal')}</a></div><button class="btn btn-dark" data-action="quote">Обсудить мой макет ${icon('arrow')}</button></div></article>`;}
function howPage(){return `${breadcrumb('Как заказать')}<section class="container page-intro"><div class="eyebrow">ОТ ПЕРВОГО СООБЩЕНИЯ ДО ГОТОВОГО ИЗДЕЛИЯ</div><h1>Всё по <i>порядку.</i></h1><p>Понятный процесс, в котором вы знаете, что произойдёт дальше.</p></section><section class="container section-bottom">${steps()}<div class="how-detail-grid">${[['Что подготовить','Изделие, тираж, размер, желаемая дата. Макет, логотип или пример, если они есть. Если пока есть только идея, начнём с неё.'],['Что входит в согласование','Состав заказа, материал, окончательная стоимость, макет и срок. Изготовление начинается после подтверждения согласованных условий.'],['Как передать файлы','Подготовьте заявку на сайте, затем передайте её и исходники сотруднику в Telegram, по электронной почте или через действующую форму на официальном сайте.'],['Как получить результат','Самовывоз на Гикало, 28. Возможность, стоимость и условия доставки уточните у сотрудника. Готовность подтверждается типографией.']].map(([t,d],i)=>`<article><span>0${i+1}</span><h2>${t}</h2><p>${d}</p></article>`).join('')}</div><div class="action-row"><button class="btn btn-dark" data-action="quote">Начать заказ ${icon('arrow')}</button>${link('#/guide/file','Проверить требования к макету')}</div></section><section class="section section-tint"><div class="container faq-section"><div><div class="eyebrow">ОТВЕТЫ ДО НАЧАЛА</div><h2>Остались вопросы?</h2></div>${faqBlock()}</div></section>`;}
function aboutPage(){return `${breadcrumb('О типографии')}<section class="container editorial-hero"><div><div class="eyebrow">ПОПУГАЙ · ПЕЧАТНЫЙ ЦЕНТР В МИНСКЕ</div><h1>Любим, когда<br>идея становится<br><i>вещью.</i></h1><p>Печатная карточка, которую передают при знакомстве. Любимая кружка. Вывеска для нового места. В каждом изделии есть чья-то задумка.</p><p>Мы помогаем придать ей форму.</p></div><div class="editorial-picture about-picture">${photo('interior','Настоящий интерьер печатного центра Попугай','',true)}<span class="editorial-sticker">ГИКАЛО, 28<br>ЗА ЦУМОМ</span></div></section><section class="section section-tint"><div class="container split-section"><div><div class="eyebrow">МНОГО ЗАДАЧ. ОДНО МЕСТО.</div><h2>Печать для жизни.<br>И для вашего дела.</h2></div><div><p class="body-large">«Попугай» объединяет оперативную полиграфию, фотоуслуги, дизайн, сувенирную и широкоформатную печать.</p><p>Работаем с частными клиентами и организациями. Помогаем с готовыми макетами и проектами, которые пока существуют только в голове.</p>${link('#/catalog','Посмотреть возможности')}</div></div></section><section class="section container">${sectionHead('01','ОТНОШЕНИЕ К РАБОТЕ','Внимание — в конкретных вещах.')}<div class="values-grid">${[['Сначала понять задачу','Для чего изделие, кто будет им пользоваться и что важно в результате. Эти вопросы помогают выбрать подходящее исполнение.'],['Разобраться с материалом','Размер, основа и способ нанесения влияют на вид и ощущение. Их согласуют с учётом вашего макета и задачи.'],['Проверить перед печатью','Версия файла, параметры и согласование — важная часть работы до изготовления. Лучше задать вопрос вовремя.']].map(([t,d],i)=>`<article><span>0${i+1} /</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></section><section class="section container about-details"><div class="about-detail-photo">${photo('clear-card','Фирменная прозрачная карточка Попугай')}</div><div><div class="eyebrow">ОТКРЫТО О КОМПАНИИ</div><h2>За названием —<br>реальный печатный центр.</h2><dl class="company-details"><div><dt>Предприниматель</dt><dd>ИП Фролов Михаил Вячеславович</dd></div><div><dt>УНП</dt><dd>192131673</dd></div><div><dt>Свидетельство</dt><dd>№ 192131673 от 01.10.2013, Мингорисполком</dd></div><div><dt>Адрес печатного центра</dt><dd>${contact.address}</dd></div></dl>${link('#/contacts','Контакты и как добраться')}</div></section>`;}
function contactsPage(){return `${breadcrumb('Контакты')}<section class="container page-intro"><div class="eyebrow">ПОЗНАКОМИМСЯ?</div><h1>Заглядывайте<br>в <i>«Попугай».</i></h1><p>Покажем материалы, обсудим идею и поможем с заказом.</p></section><section class="container contact-grid"><div class="contact-main"><span class="eyebrow">ПЕЧАТНЫЙ ЦЕНТР</span><h2>Минск,<br>Гикало, 28.</h2><p>За ЦУМом, в жилом пятиэтажном здании.<br>Станция метро «Площадь Якуба Коласа».</p><div class="contact-hours">${icon('clock')}<div><strong>${contact.hours}</strong><span>Изменения в праздничные дни уточняйте по телефону.</span></div></div><a href="${contact.map}" target="_blank" rel="noopener" class="btn btn-dark">Построить маршрут ${icon('diagonal')}</a><div class="contact-call"><a href="tel:${contact.tel}">${contact.phone}</a><span>Единый номер для розницы и организаций</span></div></div><div class="contact-photo">${photo('interior','Интерьер печатного центра по адресу Гикало, 28','',true)}<div class="contact-photo-caption"><span>УЗНАТЬ МЕСТО ИЗНУТРИ</span><strong>Здесь ваши идеи становятся печатью.</strong></div></div></section><section class="section container"><div class="contact-channels"><article><span class="eyebrow">ЧАСТНЫМ КЛИЕНТАМ</span><h3>Расскажите, что задумали.</h3><a href="${contact.telegram}" target="_blank" rel="noopener" class="text-link">Telegram @popygaiby ${icon('diagonal')}</a><a href="mailto:${contact.email}">${contact.email}</a><p>Приложите файл и укажите изделие, размер, количество и желаемую дату.</p></article><article><span class="eyebrow">ОРГАНИЗАЦИЯМ</span><h3>Обсудим ваш проект.</h3><a href="mailto:${contact.businessEmail}" class="text-link">${contact.businessEmail} ${icon('diagonal')}</a><a href="tel:${contact.tel}">${contact.phone}</a><p>Отправьте техническое задание, список позиций и реквизиты для подготовки предложения.</p></article><article><span class="eyebrow">ПОЛУЧЕНИЕ</span><h3>Когда заказ готов.</h3><a href="#/orders" class="text-link">Мой заказ ${icon('arrow')}</a><p>Дождитесь подтверждения готовности. Возможность и условия доставки согласуйте со специалистом.</p></article></div></section>`;}
function pricesPage(){return `${breadcrumb('Цены и расчёт')}<section class="container page-intro"><div class="eyebrow">СТОИМОСТЬ С ПОНЯТНЫМ СОСТАВОМ</div><h1>Сначала детали.<br>Потом <i>точная цена.</i></h1><p>Для стандартных вариантов есть предварительный расчёт. Особенные задачи обсудим отдельно.</p></section><section class="container section-bottom"><div class="prices-layout"><div><div class="price-table"><div class="price-table-head"><span>Стандартная комплектация</span><span>По прайсу</span></div>${[products[0],products[3],products[7]].map(p=>`<a href="#/product/${p.id}"><div><strong>${p.title}</strong><span>${p.spec}</span></div><div><strong>${money(p.price)} BYN</strong><span>${p.unit} ${icon('diagonal')}</span></div></a>`).join('')}</div><p class="price-footnote">Проверено ${priceMeta.checked} по <a href="${priceMeta.source}" target="_blank" rel="noopener">официальному прайсу</a>. Это исходные опубликованные тарифы; актуальность и итог подтверждает сотрудник.</p><div class="price-explanation"><h2>Что влияет на стоимость</h2>${[['Тираж','Количество экземпляров и разных макетов. В калькуляторе комплекты суммируются без предполагаемой тиражной скидки.'],['Материал и печать','Размер, тип основы, цветность и количество сторон.'],['Подготовка и обработка','Дизайн, исправления, резка, ламинирование, переплёт и другие работы рассчитываются по составу задания.'],['Срок и получение','Срочность, доступность заготовок и доставка согласуются отдельно.']].map(([t,d])=>`<div><h3>${t}</h3><p>${d}</p></div>`).join('')}</div></div><aside class="price-aside"><img src="./assets/brand/parrot.png" alt=""><h3>Есть список<br>того, что нужно?</h3><p>Пришлите его вместе с макетами. Подготовим расчёт для всей задачи.</p><button class="btn btn-dark" data-action="quote">Собрать заявку ${icon('arrow')}</button><a href="https://popygai.by/assets/frontend/pdf/price_2025.pdf" target="_blank" rel="noopener" class="text-link">Официальный PDF-прайс ${icon('download')}</a></aside></div></section>`;}
function ordersPage(){return `${breadcrumb('Мой заказ')}<section class="container page-intro"><div class="eyebrow">ВЕРНУТЬСЯ К ВАШЕЙ ИДЕЕ</div><h1>Всё важное —<br><i>под рукой.</i></h1><p>Здесь — заявки, которые вы сохранили в этом браузере. Статус принятого заказа проверяется у типографии.</p></section><section class="container section-bottom orders-layout"><div><div class="drafts-heading"><h2>Мои черновики</h2><span>${drafts.length}</span></div>${drafts.length?drafts.map(d=>`<article class="draft-card"><div><span class="draft-state">ЧЕРНОВИК · НЕ ОТПРАВЛЕН</span><h3>${esc(d.title)}</h3><p>${new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',year:'numeric'}).format(new Date(d.created))} · ${esc(d.id)}</p><span>${d.items.length} поз. · ${d.fileNames?.length||0} файлов в описании</span></div><div><button class="text-link" data-draft="${esc(d.id)}">Открыть заявку ${icon('arrow')}</button><button class="delete-draft" data-delete-draft="${esc(d.id)}">Удалить черновик</button></div></article>`).join(''):`<div class="empty-state"><img src="./assets/brand/parrot.png" alt=""><h3>Здесь начнётся ваша история печати.</h3><p>Подготовьте заявку и сохраните её, чтобы вернуться к деталям позже.</p><button class="btn btn-dark" data-action="quote">Начать с идеи ${icon('arrow')}</button></div>`}<p class="small-text">Черновики хранятся только в этом браузере. Файлы не сохраняются: при отправке их нужно приложить заново.</p></div><aside class="order-status"><span class="eyebrow">УЖЕ ПЕРЕДАЛИ ЗАКАЗ?</span><h3>Узнайте готовность<br>в типографии.</h3><p>Если сотрудник выдал номер заказа, используйте проверку на действующем сайте или напишите в Telegram.</p><a href="https://popygai.by/order" class="btn btn-dark" target="_blank" rel="noopener">Проверить готовность ${icon('diagonal')}</a><a href="${contact.telegram}" class="text-link" target="_blank" rel="noopener">Связаться с сотрудником ${icon('diagonal')}</a></aside></section>`;}
function privacyPage(){return `${breadcrumb('Конфиденциальность')}<section class="container legal-page"><div class="eyebrow">ОБРАБОТКА ДАННЫХ В ЭТОЙ ВЕРСИИ САЙТА</div><h1>Ваши файлы<br>и <i>данные.</i></h1><p class="body-large">Сайт помогает подготовить заявку и передать её в печатный центр по выбранному вами каналу связи.</p><h2>Файлы</h2><p>Выбранные в форме файлы не загружаются на сервер. Их названия добавляются в описание заявки. Исходники необходимо самостоятельно приложить в Telegram, почтовом приложении или действующей форме типографии.</p><h2>Черновики</h2><p>При нажатии «Сохранить черновик» параметры, текст и введённые контактные данные сохраняются в localStorage вашего браузера. Файлы не сохраняются. Удалить черновик можно на странице «Мой заказ». Не сохраняйте конфиденциальные сведения на общем устройстве.</p><h2>Передача заявки</h2><p>Заявка не поступает в производство при её подготовке на сайте. Передача происходит, когда вы сами отправляете сообщение или письмо. Правила выбранного сервиса связи применяются при его использовании.</p><h2>Внешние сервисы</h2><p>Ссылки на Telegram, карты, электронную почту и официальный сайт открывают соответствующие сервисы. Их условия обработки данных определяются их владельцами.</p><h2>К кому обратиться</h2><p>Контакты печатного центра: <a href="mailto:${contact.email}">${contact.email}</a>, <a href="tel:${contact.tel}">${contact.phone}</a>. ИП Фролов Михаил Вячеславович, УНП 192131673.</p></section>`;}
function notFound(){return `<section class="container empty-state error-page"><img src="./assets/brand/parrot.png" alt=""><div class="eyebrow">404 / НЕМНОГО СБИЛИСЬ С МАРШРУТА</div><h1>Эта страница<br>ещё не напечатана.</h1><p>Зато в каталоге много хороших идей.</p>${link('#/catalog','Вернуться к продукции','btn btn-dark')}</section>`;}

function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function modal(content,cls=''){modalReturn=document.activeElement;$('#overlay-root').innerHTML=`<div class="overlay-backdrop" data-action="dismiss"></div><section class="modal ${cls}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="modal-close icon-button" data-action="dismiss" aria-label="Закрыть">${icon('close')}</button>${content}</section>`;document.body.classList.add('modal-open');$('#main').inert=true;$('#site-header').inert=true;$('#site-footer').inert=true;requestAnimationFrame(()=>$('.modal input:not([type=hidden]), .modal button, .modal a')?.focus());}
function closeModal(){const ref=modalReturn;$('#overlay-root').innerHTML='';document.body.classList.remove('modal-open');$('#main').inert=false;$('#site-header').inert=false;$('#site-footer').inert=false;ref?.isConnected&&ref.focus();}
function openSearch(){modal(`<div class="eyebrow">НАЙДЁМ НУЖНОЕ</div><h2 id="modal-title">Что вы задумали?</h2><label class="search-input">${icon('search')}<input type="search" id="global-search" placeholder="Визитки, наклейки, кружки…" autocomplete="off" aria-label="Поиск изделий и памяток"></label><div id="global-results" class="global-results"></div>`,'search-modal');searchResults('');}
function searchResults(query){const normalized=query.toLowerCase().trim();const list=products.filter(p=>`${p.title} ${p.description} ${p.id==='stickers'?'стикеры этикетки':''} ${p.id==='documents'?'распечатка копия':''}`.toLowerCase().includes(normalized)).slice(0,6);$('#global-results').innerHTML=`<span class="eyebrow">${normalized?'ПРОДУКЦИЯ':'ПОПУЛЯРНОЕ'}</span>${list.map(p=>`<a href="#/product/${p.id}">${photo(p.image,p.title)}<span><strong>${p.title}</strong><small>${p.spec}</small></span>${icon('diagonal')}</a>`).join('')}${!list.length?'<p>По этому запросу ничего не нашлось. Попробуйте другое название или расскажите нам о задаче.</p><button class="text-link" data-action="quote">Помочь с выбором '+icon('arrow')+'</button>':''}${normalized?guides.filter(g=>`${g.title} ${g.desc}`.toLowerCase().includes(normalized)).map(g=>`<a href="#/guide/${g.id}">${icon('file')}<span><strong>${g.title}</strong><small>Памятка · ${g.read}</small></span>${icon('arrow')}</a>`).join(''):''}`;}
function openMenu(){modal(`<div class="eyebrow">ПОПУГАЙ · ПЕЧАТНЫЙ ЦЕНТР</div><h2 id="modal-title">Куда заглянем?</h2><nav class="mobile-menu" aria-label="Мобильная навигация">${[['catalog','Каталог'],['business','Для бизнеса'],['works','Наши работы'],['materials','Материалы'],['about','О типографии'],['guides','Полезное о печати'],['prices','Цены'],['contacts','Контакты'],['orders','Мой заказ']].map(([url,t])=>`<a href="#/${url}">${t}${icon('diagonal')}</a>`).join('')}</nav><a href="tel:${contact.tel}" class="mobile-menu-phone">${contact.phone}</a>`,'menu-modal');}

function itemDescription(item){const p=products.find(p=>p.id===item.id);const o=item.options||{};const parts=[p?.title||item.title||'Индивидуальная задача'];if(o.quantity)parts.push(`${o.quantity} ${p?.pricing==='documents'?'листов':'шт.'}`);if(o.format&&["documents","flyers"].includes(p?.pricing))parts.push(o.format);if(o.paper&&p?.pricing==="cards")parts.push(o.paper==='coated'?'Мелованная бумага':'Каландрированная бумага');if(o.color&&p?.pricing==="documents")parts.push(o.color==='bw'?'Чёрно-белая':'Цветная');if(o.sides&&p?.pricing!=='quote')parts.push(o.sides==='one'?'1 сторона':'2 стороны');if(o.material&&p?.pricing==="quote")parts.push(o.material);if(o.customSize)parts.push(o.customSize);const amount=calculatePrice(item.id,o);if(amount!==null)parts.push(`предварительно ${money(amount)} BYN`);return parts.join(' · ');}
function openQuote(items=[],draft=null){drawerItems=items;selectedFiles=[];const initial=draft||{};modal(`<div class="eyebrow">ДАВАЙТЕ НАЧНЁМ С ВАШЕЙ ИДЕИ</div><h2 id="modal-title">Обсудим заказ.</h2><p class="modal-intro">Подготовьте описание — затем передайте его сотруднику удобным способом.</p><div class="quote-selected">${items.length?items.map(item=>`<div>${icon('check')}<span>${esc(itemDescription(item))}</span></div>`).join(''):'<span>Можно начать с идеи. Изделие и параметры подберём вместе.</span>'}</div><form id="quote-form"><label class="field-label">Что хотите сделать?<textarea name="task" rows="3" placeholder="Например: наклейки на упаковку кофе, около 200 шт. Нужна помощь с материалом." required minlength="5">${esc(initial.task||'')}</textarea></label><div class="form-row"><label class="field-label">Как к вам обращаться<input name="name" autocomplete="name" placeholder="Ваше имя" value="${esc(initial.name||'')}" required maxlength="80"></label><label class="field-label">Телефон или email<input name="contact" autocomplete="email" placeholder="Чтобы обсудить детали" value="${esc(initial.contact||'')}" required maxlength="150"></label></div><div class="form-row"><label class="field-label">Желаемая дата <span class="optional">необязательно</span><input name="deadline" type="date" min="${localDate()}" value="${esc(initial.deadline||'')}"></label><label class="field-label">Макет<select name="design"><option ${initial.design==='Есть готовый макет'?'selected':''}>Есть готовый макет</option><option ${initial.design==='Нужна проверка или доработка'?'selected':''}>Нужна проверка или доработка</option><option ${!initial.design||initial.design==='Нужен дизайн с нуля'?'selected':''}>Нужен дизайн с нуля</option></select></label></div><label class="file-drop"><input id="quote-files" type="file" multiple accept=".pdf,.cdr,.ai,.eps,.svg,.tif,.tiff,.jpg,.jpeg,.png,.zip"><span class="file-drop-icon">${icon('upload')}</span><strong>Выбрать макеты</strong><span>PDF, CDR, AI, изображения или архив · до 25 МБ на файл</span></label><div class="file-list" id="file-list"></div><p class="file-note">Файлы остаются на вашем устройстве. На следующем шаге напомним приложить их к сообщению сотруднику.${initial.fileNames?.length?' В черновике были: '+esc(initial.fileNames.join(', '))+'. Выберите их заново.':''}</p><label class="checkbox-label"><input type="checkbox" name="business" ${initial.business?'checked':''}>Заказ для организации</label><label class="checkbox-label consent"><input type="checkbox" name="consent" required>Я ознакомился с <a href="#/privacy" target="_blank">информацией об обработке данных</a></label><div class="quote-form-actions"><button class="btn btn-dark" type="submit">Подготовить заявку ${icon('arrow')}</button><button class="text-link" type="button" data-action="save-draft">Сохранить черновик</button></div><p class="under-button">Стоимость и срок подтверждает сотрудник типографии.</p></form>`,'quote-modal');$('#quote-form').dataset.draft=initial.id||'';if(items.length&&!initial.task)$('#quote-form textarea').value=items.map(i=>products.find(p=>p.id===i.id)?.title||i.title).join(', ');}
function localDate(){const date=new Date();return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
function quoteData(){const form=$('#quote-form');const f=new FormData(form);return {id:form.dataset.draft||`D-${Date.now().toString(36).toUpperCase()}`,created:Date.now(),title:drawerItems.length?drawerItems.map(i=>products.find(p=>p.id===i.id)?.title||i.title).join(', '):String(f.get('task')||'Моя идея').slice(0,65),task:String(f.get('task')||'').trim(),name:String(f.get('name')||'').trim(),contact:String(f.get('contact')||'').trim(),deadline:String(f.get('deadline')||''),design:String(f.get('design')||''),business:f.get('business')==='on',items:structuredClone(drawerItems),fileNames:selectedFiles.map(f=>f.name)};}
function saveDraft(data){const index=drafts.findIndex(d=>d.id===data.id);if(index>=0)drafts[index]=data;else drafts.unshift(data);try{localStorage.setItem('popygai-drafts',JSON.stringify(drafts.slice(0,30)));toast('Черновик сохранён в этом браузере.');return true;}catch{toast('Не удалось сохранить: хранилище браузера недоступно. Скачайте описание заявки.');return false;}}
function quoteText(d){return `Заявка для печатного центра «Попугай»\n\n${d.business?'Для организации\n':''}Задача: ${d.task}\n${d.items.length?'\nИзделия:\n'+d.items.map((i,n)=>`${n+1}. ${itemDescription(i)}`).join('\n')+'\n':''}\nИмя: ${d.name}\nКонтакт: ${d.contact}\nЖелаемая дата: ${d.deadline||'обсудим'}\nМакет: ${d.design}\nФайлы для приложения: ${d.fileNames.length?d.fileNames.join(', '):'пока не выбраны'}\n\nПрошу подтвердить состав, итоговую стоимость и срок.\nРасчёт на сайте предварительный, без подтверждения готовности к печати.`;}
let preparedDraft=null;
function showPrepared(d){preparedDraft=d;const text=quoteText(d);modal(`<div class="prepared-mark">${icon('check')}</div><div class="eyebrow">ОПИСАНИЕ ГОТОВО</div><h2 id="modal-title">Осталось передать<br>его нам.</h2><p class="modal-intro">Выберите канал связи и отправьте сообщение. После этого сотрудник сможет подтвердить детали.</p><div class="prepared-reminder">${icon('info')}<p><strong>Заявка ещё не отправлена в типографию.</strong><br>${d.fileNames.length?'Приложите выбранные файлы к сообщению: '+esc(d.fileNames.join(', '))+'.':'Если есть макет, приложите его к сообщению.'}</p></div><label class="field-label">Текст вашей заявки<textarea id="prepared-text" rows="9" readonly>${esc(text)}</textarea></label><div class="handoff-actions"><button class="btn btn-dark" data-action="copy-quote">${icon('copy')}Скопировать описание</button><a href="${contact.telegram}" class="btn btn-outline" target="_blank" rel="noopener">Открыть Telegram ${icon('diagonal')}</a><a href="mailto:${d.business?contact.businessEmail:contact.email}?subject=${encodeURIComponent('Заявка: '+d.title)}&body=${encodeURIComponent(text)}" class="btn btn-outline">${icon('mail')}Открыть письмо</a></div><div class="prepared-bottom"><button class="text-link" data-action="download-quote">Скачать описание ${icon('download')}</button><button class="text-link" data-action="save-prepared">Сохранить черновик ${icon('bag')}</button><button class="text-link" data-action="edit-quote">Изменить заявку</button></div><a href="https://popygai.by/order" target="_blank" rel="noopener" class="official-order">Или загрузить файлы через действующую форму типографии ${icon('diagonal')}</a>`,'quote-modal prepared-modal');}
async function copyText(value){try{await navigator.clipboard.writeText(value);toast('Текст скопирован. Вставьте его в сообщение и приложите файлы.');}catch{const el=$('#prepared-text');el?.select();toast('Выделили текст. Скопируйте его вручную.');}}
function downloadText(data){const blob=new Blob([quoteText(data)],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`popygai-${data.id}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function showFiles(){const list=$('#file-list');if(!list)return;list.innerHTML=selectedFiles.map((f,i)=>`<div>${icon('file')}<span><strong>${esc(f.name)}</strong><small>${(f.size/1048576).toFixed(2)} МБ · выбрано для приложения</small></span><button type="button" data-remove-file="${i}" class="icon-button" aria-label="Убрать файл ${esc(f.name)}">${icon('close')}</button></div>`).join('');}

function render(){
 const hash=location.hash.replace(/^#/,'')||((document.body.dataset.route||'/')+location.search);const [pathname,query='']=hash.split('?');route=pathname;const params=new URLSearchParams(query);currentProduct=null;
 const pages={'/':home,'/catalog':()=>catalog(params),'/business':businessPage,'/works':()=>worksPage(params),'/materials':materialsPage,'/guides':guidesPage,'/how':howPage,'/about':aboutPage,'/contacts':contactsPage,'/prices':pricesPage,'/orders':ordersPage,'/privacy':privacyPage};
 const content=pages[pathname]?pages[pathname]():pathname.startsWith('/product/')?productPage(pathname.split('/')[2]):pathname.startsWith('/work/')?workPage(pathname.split('/')[2]):pathname.startsWith('/guide/')?guidePage(pathname.split('/')[2]):notFound();
 closeModal();$('#main').innerHTML=content;
 const titles={'/':'Печатаем ваши идеи','/catalog':'Каталог','/business':'Для бизнеса','/works':'Наши работы','/materials':'Материалы','/guides':'Полезное о печати','/how':'Как заказать','/about':'О типографии','/contacts':'Контакты','/prices':'Цены и расчёт','/orders':'Мой заказ','/privacy':'Конфиденциальность'};
 document.title=`${currentProduct?.title||titles[pathname]||'Печатный центр'} — Попугай`;
 $$('[data-nav]').forEach(a=>{const active=pathname==='/'+a.dataset.nav||(a.dataset.nav==='catalog'&&pathname.startsWith('/product/'))||(a.dataset.nav==='works'&&pathname.startsWith('/work/'));if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 if(pathname==='/catalog')filterCatalog(params.get('category')||'all');if(currentProduct)updateQuote();
 observer?.disconnect();observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('revealed');observer.unobserve(e.target);}}),{threshold:.06});
 $$('.section-head,.material-row,.business-band-inner,.step,.visit-grid,.values-grid').forEach(el=>{el.classList.add('reveal');observer.observe(el);});
 window.scrollTo({top:0,behavior:'instant'});
}
export const staticRoutes=['/','/catalog','/business','/works','/materials','/guides','/how','/about','/contacts','/prices','/orders','/privacy',...products.map(p=>'/product/'+p.id),...works.map(w=>'/work/'+w.id),...guides.map(g=>'/guide/'+g.id)];
export function prerender(pathname){
 const pages={'/':home,'/catalog':()=>catalog(new URLSearchParams()),'/business':businessPage,'/works':()=>worksPage(new URLSearchParams()),'/materials':materialsPage,'/guides':guidesPage,'/how':howPage,'/about':aboutPage,'/contacts':contactsPage,'/prices':pricesPage,'/orders':ordersPage,'/privacy':privacyPage};
 let content=pages[pathname]?pages[pathname]():pathname.startsWith('/product/')?productPage(pathname.split('/')[2]):pathname.startsWith('/work/')?workPage(pathname.split('/')[2]):pathname.startsWith('/guide/')?guidePage(pathname.split('/')[2]):notFound();
 if(pathname==='/catalog')content=content.replace('<div class="product-grid catalog-grid" id="catalog-results"></div>',`<div class="product-grid catalog-grid" id="catalog-results">${products.map(productCard).join('')}</div>`);
 if(pathname.startsWith('/product/')&&currentProduct){
   const total=calculatePrice(currentProduct.id,config);
   content=content.replace('<strong id="quote-total"></strong>',`<strong id="quote-total">${total===null?'По запросу':money(total)+' BYN'}</strong>`).replace('<p class="summary-note" id="quote-note"></p>',`<p class="summary-note" id="quote-note">${priceMeta.note}</p>`);
 }
 const heading=content.match(/<h1[^>]*>([\s\S]*?)<\/h1>/)?.[1]||'Печатный центр';
 const title=heading.replace(/<svg[\s\S]*?<\/svg>/g,'').replace(/<br\s*\/?\s*>/g,' ').replace(/<[^>]*>/g,'').replace(/\s+/g,' ').replace(' .','.').trim()+' — Попугай';
 return {content,title,header:headerMarkup(),footer:footerMarkup()};
}
if(typeof document!=='undefined'){
document.addEventListener('click',async event=>{
 const skip=event.target.closest('.skip-link');if(skip){event.preventDefault();$('#main').focus();$('#main').scrollIntoView({block:'start'});return;}
 const action=event.target.closest('[data-action]');
 if(action){const name=action.dataset.action;
  if(name==='dismiss')closeModal();if(name==='search')openSearch();if(name==='menu')openMenu();if(name==='quote')openQuote();
  if(name==='save-draft'){const form=$('#quote-form');if(form.reportValidity())saveDraft(quoteData());}
  if(name==='copy-quote'&&preparedDraft)await copyText($('#prepared-text').value);
  if(name==='download-quote'&&preparedDraft)downloadText(preparedDraft);
  if(name==='save-prepared'&&preparedDraft)saveDraft(preparedDraft);
  if(name==='edit-quote'&&preparedDraft)openQuote(preparedDraft.items,preparedDraft);
 }
 const filter=event.target.closest('[data-filter]');if(filter){const category=filter.dataset.filter;$$('[data-filter]').forEach(b=>{b.classList.toggle('active',b===filter);b.setAttribute('aria-pressed',String(b===filter));});filterCatalog(category,$('#catalog-search').value);history.replaceState(null,'',`#/catalog${category==='all'?'':'?category='+category}`);}
 const material=event.target.closest('[data-material]');if(material){const m=materials.find(m=>m.id===material.dataset.material);$$('[data-material]').forEach(b=>{b.classList.toggle('active',b===material);b.setAttribute('aria-selected',String(b===material));});$('#material-stage').innerHTML=materialVisual(m);$('#material-detail').innerHTML=`<strong>${m.feel}</strong><p>${m.description}</p>`;}
 const quantity=event.target.closest('[data-quantity]');if(quantity){const input=$('[name=quantity]');const step=Number(input.step||1);input.value=Math.max(Number(input.min),Math.min(Number(input.max),Number(input.value)+(quantity.dataset.quantity==='plus'?step:-step)));input.dispatchEvent(new Event('input',{bubbles:true}));}
 const bundle=event.target.closest('[data-bundle]');if(bundle){const items=$$(`[data-bundle-item="${bundle.dataset.bundle}"]:checked`).map(i=>({id:i.value,options:{}}));if(items.length)openQuote(items);else toast('Выберите хотя бы одно изделие для комплекта.');}
 const similar=event.target.closest('[data-similar]');if(similar)openQuote([{id:similar.dataset.similar,options:{}}]);
 const draftButton=event.target.closest('[data-draft]');if(draftButton){const d=drafts.find(x=>x.id===draftButton.dataset.draft);if(d)openQuote(d.items,d);}
 const deleteDraft=event.target.closest('[data-delete-draft]');if(deleteDraft){drafts=drafts.filter(d=>d.id!==deleteDraft.dataset.deleteDraft);try{localStorage.setItem('popygai-drafts',JSON.stringify(drafts));}catch{}render();toast('Черновик удалён из этого браузера.');}
 const remove=event.target.closest('[data-remove-file]');if(remove){selectedFiles.splice(Number(remove.dataset.removeFile),1);showFiles();}
 const lightbox=event.target.closest('[data-lightbox]');if(lightbox)modal(`<h2 class="sr-only" id="modal-title">${esc(lightbox.dataset.caption)}</h2>${photo(lightbox.dataset.lightbox,lightbox.dataset.caption,'lightbox-image',true)}<p class="lightbox-caption">${esc(lightbox.dataset.caption)} · из портфолио «Попугая»</p>`,'lightbox-modal');
 const scroll=event.target.closest('[data-scroll]');if(scroll){event.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}
 const internal=event.target.closest('a[href^="#/"]');if(internal&&$('.modal')){if(internal.hash===location.hash)closeModal();}
});
document.addEventListener('input',event=>{
 if(event.target.id==='global-search')searchResults(event.target.value);
 if(event.target.id==='catalog-search')filterCatalog($('[data-filter].active')?.dataset.filter||'all',event.target.value);
 if(event.target.closest('#product-config-form')){const f=new FormData($('#product-config-form'));config={...config,...Object.fromEntries(f)};updateQuote();}
});
document.addEventListener('change',event=>{
 if(event.target.closest('#product-config-form')){const f=new FormData($('#product-config-form'));config={...config,...Object.fromEntries(f)};$$('.option').forEach(el=>el.classList.toggle('selected',$('input',el).checked));if(currentProduct.pricing==='cards'){const hint=$('.option-hint');hint.textContent=`${config.sides==='two'?'300':'350'} г/м² · ${config.paper==='coated'?'гладкая универсальная основа':'плотная бумага с гладкой поверхностью'}`;}updateQuote();}
 if(event.target.id==='quote-files'){for(const file of event.target.files){if(file.size>25*1048576){toast(`Файл ${file.name} больше 25 МБ. Передайте ссылку сотруднику.`);continue;}if(selectedFiles.length>=10){toast('Можно выбрать до 10 файлов. Остальные передайте сотруднику отдельно.');break;}if(!selectedFiles.some(f=>f.name===file.name&&f.size===file.size))selectedFiles.push(file);}showFiles();event.target.value='';}
});
document.addEventListener('submit',event=>{
 if(event.target.id==='product-config-form'){event.preventDefault();const f=new FormData(event.target);config={...config,...Object.fromEntries(f)};if(currentProduct.pricing!=='quote'&&calculatePrice(currentProduct.id,config)===null){toast('Проверьте количество и параметры.');return;}openQuote([{id:currentProduct.id,options:{...config}}]);}
 if(event.target.id==='quote-form'){event.preventDefault();const d=quoteData();if(!validContact(d.contact)){$('[name=contact]',event.target).setCustomValidity('Укажите полный email или номер телефона.');$('[name=contact]',event.target).reportValidity();$('[name=contact]',event.target).addEventListener('input',e=>e.target.setCustomValidity(''),{once:true});return;}showPrepared(d);}
});
document.addEventListener('keydown',event=>{
 const material=event.target.closest('[data-material]');if(material&&['ArrowRight','ArrowLeft','Home','End'].includes(event.key)){event.preventDefault();const tabs=$$('[data-material]');const index=tabs.indexOf(material);const next=event.key==='Home'?tabs[0]:event.key==='End'?tabs.at(-1):tabs[(index+(event.key==='ArrowRight'?1:tabs.length-1))%tabs.length];next.click();next.focus();return;}
 const dialog=$('.modal');if(!dialog)return;
 if(event.key==='Escape'){event.preventDefault();closeModal();}
 if(event.key==='Tab'){const elements=$$('a[href],button:not([disabled]),input:not([type=hidden]),textarea,select,[tabindex="0"]',dialog).filter(e=>e.getClientRects().length);const first=elements[0],last=elements.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
});
window.addEventListener('hashchange',render);
$('#site-header').innerHTML=headerMarkup();$('#site-footer').innerHTML=footerMarkup();render();
}
